// Idioma de la vista: la preferencia guardada en la sesión, si no el idioma
// de la cuenta, si no español. El toggle re-renderiza la vista actual.
function tcLang() {
  try {
    const s = sessionStorage.getItem('tc_lang');
    if (s === 'es' || s === 'en') return s;
  } catch (e) {}
  try { if (typeof ME !== 'undefined' && ME && ME.lang === 'en') return 'en'; } catch (e) {}
  return 'es';
}
function tcToggleLang() {
  try { sessionStorage.setItem('tc_lang', tcLang() === 'es' ? 'en' : 'es'); } catch (e) {}
  try { render(); } catch (e) {}
}

function terminosView() {
  const d = TC_DATA[tcLang()] || TC_DATA.es;
  const secs = d.sections.map((s) => '<h2>' + s[0] + '</h2>' + s[1]).join('');
  return '<style>.tc-card h1{font-size:24px;margin:0 0 4px}.tc-card h2{font-size:19px;margin:28px 0 10px}.tc-card h3{font-size:16px;margin:20px 0 6px}.tc-card p,.tc-card li{font-size:15px;line-height:1.65;margin-bottom:10px}.tc-card ul{padding-left:20px}.tc-card a{color:var(--cel)}</style>'
    + '<div class="apv-wrap"><div class="card tc-card">'
    + '<h1>' + d.title + '</h1>'
    + '<p class="hint" style="margin:0 0 4px">' + d.meta + '</p>'
    + '<p style="margin:0 0 16px"><a href="#" onclick="tcToggleLang();return false" style="color:var(--cel);font-weight:700">' + d.toggle + '</a></p>'
    + d.intro + d.defs + secs + d.close
    + '</div></div>';
}
